// Generated by OrchestKit Claude Plugin
// Created: 2026-09-06
//
// Pins the audit/rewrite error handling in src/workflows/write-sections.js.
//
// A live v0.10.0 /write run spawned 223 agents, burned ~6.1M subagent tokens
// and ran 66 minutes for a partial result, because a quota/session-limit
// error was scored the same as an auditor FAIL verdict:
//
//   agent() resolves to null on a terminal API error (per the Workflow
//   authoring contract) -> rawTextOf(null) -> '""' -> parsePostFenceVerdict
//   found no VERDICT line and defaulted to 'FAIL' -> the script re-spawned
//   section-writer to rewrite, which failed the same infrastructure way,
//   whose own null was logged as "no usable text" -> the loop re-audited.
//   Each cycle cost two more agent calls and pushed the quota further
//   underwater, for every paragraph, up to rewriteCycles.max.
//
// Separately, resumeFromRunId without args (or any run where the
// draft-audit stage does not run at all) reported the top-level `outcome`
// as 'PASS' with zero sections and zero agents run -- the same "an unrun
// gate is not a pass" failure the plugin's own 0.9.0 anti-AI gate removal
// was about, one level up.
//
// This test loads the actual script source and executes it inside a
// wrapping async function with mocked agent()/pipeline()/phase()/log()
// globals -- the same technique the shipped script requires (it has no
// filesystem or Node API access and is never `require`-able directly),
// extended here to run the whole script rather than eval-slicing one
// function, because the defect is in how two stages interact.

const fs = require('fs');
const path = require('path');
const assert = require('assert');
const vm = require('vm');

const SRC_PATH = path.join(__dirname, '..', 'src', 'workflows', 'write-sections.js');
const SRC = fs.readFileSync(SRC_PATH, 'utf8').replace('export const meta', 'const meta');

function buildRunner() {
  const script = new vm.Script(
    '(async function __run(agent, pipeline, phase, log, args) {\n' + SRC + '\n});',
    { filename: SRC_PATH }
  );
  return script.runInThisContext();
}

// Sequential pipeline mock: real pipeline() has no barrier between items, but
// per-item stage1-then-stage2 sequencing is what the script's correctness
// depends on, and that is what this mock reproduces.
async function pipelineMock(items, ...stages) {
  const results = [];
  for (let i = 0; i < items.length; i += 1) {
    let value = items[i];
    for (const stage of stages) {
      value = await stage(value, items[i], i);
    }
    results.push(value);
  }
  return results;
}

function baseThresholds() {
  return {
    rewriteCycles: { max: 3 },
    writerUnit: { targetWords: 300, minWords: 200, maxWords: 400 },
  };
}

function oneUnitOutline() {
  return { units: [{ id: 'u1', title: 'Unit One', claim: 'c1', evidence: ['e1'] }] };
}

async function run(args, agentImpl) {
  const runner = buildRunner();
  const calls = [];
  const agent = async (prompt, opts) => {
    calls.push({ label: (opts && opts.label) || null, prompt: prompt });
    return agentImpl(prompt, opts || {});
  };
  const log = () => {};
  const result = await runner(agent, pipelineMock, () => {}, log, args);
  return { result: result, calls: calls };
}

function countLabel(calls, prefix) {
  return calls.filter((c) => typeof c.label === 'string' && c.label.indexOf(prefix) === 0).length;
}

(async () => {
  // A. parsePostFenceVerdict must return null, never 'FAIL', when no VERDICT
  // line is present -- lifted out the same way flattenUnits is, since it is
  // self-contained.
  {
    const start = SRC.indexOf('function parsePostFenceVerdict');
    const end = SRC.indexOf('function paragraphId');
    assert.ok(start !== -1 && end > start, 'parsePostFenceVerdict not found');
    const scope = {};
    vm.createContext(scope);
    vm.runInContext(SRC.slice(start, end) + '\nthis.parsePostFenceVerdict = parsePostFenceVerdict;', scope);
    assert.strictEqual(scope.parsePostFenceVerdict(''), null, 'empty auditor text must not default to FAIL');
    assert.strictEqual(scope.parsePostFenceVerdict('some prose with no verdict line'), null);
    assert.strictEqual(scope.parsePostFenceVerdict('```text\nfoo\n```\nVERDICT: PASS'), 'PASS');
    assert.strictEqual(scope.parsePostFenceVerdict('```text\nfoo\n```\nVERDICT: FAIL'), 'FAIL');
  }

  // B. A quota-dead auditor call (agent() -> null) must abort the paragraph
  // as ERROR on the FIRST attempt, never trigger a rewrite, and never
  // consume the rest of the rewriteCycles cap.
  {
    const { result, calls } = await run(
      { outline: oneUnitOutline(), thresholds: baseThresholds() },
      (prompt, opts) => {
        const label = opts.label || '';
        if (label.indexOf('draft:') === 0) return { unitId: 'u1', paragraphs: [{ paragraphIndex: 1, text: 'Draft text.' }] };
        if (label.indexOf('audit:') === 0) return null; // simulated quota/session-limit failure
        if (label.indexOf('rewrite:') === 0) return { paragraphIndex: 1, text: 'should never be called' };
        if (label === 'synthesize') return 'synthesized';
        if (label === 'abstract') return { abstract: 'abstract text' };
        if (label === 'scorecard') return { dimensions: [{ id: 'structure', score: 5 }], total: 30 };
        return null;
      }
    );
    assert.strictEqual(countLabel(calls, 'audit:'), 1, 'must not retry the auditor after a null (terminal-error) response');
    assert.strictEqual(countLabel(calls, 'rewrite:'), 0, 'a null auditor response must never trigger a rewrite');
    const paragraph = result.sections[0].paragraphs[0];
    assert.strictEqual(paragraph.outcome, 'ERROR');
    assert.strictEqual(paragraph.attempts, 1);
    assert.ok(/terminal API error/.test(paragraph.errorReason || ''));
    assert.strictEqual(result.outcome, 'ERROR', 'a run with an errored paragraph must not report PASS or NEEDS_REVIEW');
    assert.deepStrictEqual(result.errored.map((e) => e.paragraphIndex), [1]);
  }

  // C. resumeFromRunId-without-args shape: no outline.units, so the
  // draft-audit gate never runs. The top-level outcome must say SKIPPED, not
  // PASS -- zero sections produced is not evidence of a passing article.
  {
    const { result, calls } = await run(
      { outline: { units: [] }, thresholds: baseThresholds() },
      () => { throw new Error('no agent should be called when there are zero units'); }
    );
    assert.strictEqual(calls.length, 0);
    assert.strictEqual(result.sections.length, 0);
    assert.strictEqual(result.outcome, 'SKIPPED', 'an unrun draft-audit stage must not report PASS');
    const draftAuditGate = result.gates.find((g) => g.stage === 'draft-audit');
    assert.strictEqual(draftAuditGate.ran, false);
  }

  // D. A quota-dead DRAFT call (agent() -> null before any paragraph exists)
  // must not silently collapse to "0 paragraphs, unit done" -- it must
  // report the unit as ERROR.
  {
    const { result } = await run(
      { outline: oneUnitOutline(), thresholds: baseThresholds() },
      (prompt, opts) => {
        const label = opts.label || '';
        if (label.indexOf('draft:') === 0) return null; // simulated quota failure
        if (label === 'synthesize') return 'synthesized';
        if (label === 'abstract') return { abstract: 'abstract text' };
        if (label === 'scorecard') return { dimensions: [{ id: 'structure', score: 5 }], total: 30 };
        return null;
      }
    );
    assert.strictEqual(result.sections[0].paragraphs.length, 1, 'a dead draft call must still surface as one ERROR entry, not an empty paragraph array');
    assert.strictEqual(result.sections[0].paragraphs[0].outcome, 'ERROR');
    assert.strictEqual(result.outcome, 'ERROR');
  }

  // E. A unit with two paragraphs whose batched audit call dies (null): the
  // audit is batched per unit per round (2026-09-15), so ONE auditor call
  // covers both paragraphs. Both must surface as ERROR with the terminal-error
  // reason, in order, and the unit must stop spending -- no second audit
  // round and no rewrite under an active outage. (Pre-batching this asserted
  // a sequential "skipped: a prior paragraph already errored" reason for p2;
  // that sequential semantics no longer exists by design.)
  {
    const { result, calls } = await run(
      { outline: oneUnitOutline(), thresholds: baseThresholds() },
      (prompt, opts) => {
        const label = opts.label || '';
        if (label.indexOf('draft:') === 0) {
          return { unitId: 'u1', paragraphs: [{ paragraphIndex: 1, text: 'P1.' }, { paragraphIndex: 2, text: 'P2.' }] };
        }
        if (label === 'audit:u1:r1') return null;
        if (label.indexOf('audit:') === 0) throw new Error('no further audit round may run once the batch audit call has errored');
        if (label.indexOf('rewrite:') === 0) throw new Error('a null batch audit must never trigger a rewrite');
        if (label === 'synthesize') return 'synthesized';
        if (label === 'abstract') return { abstract: 'abstract text' };
        if (label === 'scorecard') return { dimensions: [{ id: 'structure', score: 5 }], total: 30 };
        return null;
      }
    );
    assert.strictEqual(countLabel(calls, 'audit:'), 1);
    assert.strictEqual(countLabel(calls, 'rewrite:'), 0);
    const paragraphs = result.sections[0].paragraphs;
    assert.deepStrictEqual(paragraphs.map((p) => p.paragraphIndex), [1, 2]);
    assert.strictEqual(paragraphs[0].outcome, 'ERROR');
    assert.strictEqual(paragraphs[1].outcome, 'ERROR');
    assert.ok(/terminal API error/.test(paragraphs[1].errorReason || ''));
  }

  // F. Regression guard: a genuine PASS run is unaffected by the error-path
  // changes.
  {
    const { result } = await run(
      { outline: oneUnitOutline(), thresholds: baseThresholds() },
      (prompt, opts) => {
        const label = opts.label || '';
        if (label.indexOf('draft:') === 0) return { unitId: 'u1', paragraphs: [{ paragraphIndex: 1, text: 'Draft text.' }] };
        if (label.indexOf('audit:') === 0) return { results: [{ paragraphIndex: 1, verdict: 'PASS', feedback: 'all claims verified' }] };
        if (label === 'synthesize') return 'synthesized';
        if (label === 'abstract') return { abstract: 'abstract text' };
        if (label === 'scorecard') return { dimensions: [{ id: 'structure', score: 5 }], total: 30 };
        return null;
      }
    );
    assert.strictEqual(result.sections[0].paragraphs[0].outcome, 'PASS');
    assert.strictEqual(result.outcome, 'PASS');
    assert.deepStrictEqual(result.errored, []);
  }

  console.log('test_write_sections_audit_error: assertions OK');
})().catch((err) => {
  console.error(err);
  process.exit(1);
});
